window.products.push({"id":770538,"name":"Govinda Wooden Coffin Incense Burner - 12\" (OM)","category":"homeandappliances","retail price":11.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81-6sJXV8-L._AC_SL1500_.jpg","description":"Govinda 12\" OM Wooden Coffin Incense Burner.   This beautifully handcrafted wooden incense sticks holder allows one to store away incense sticks in style. These sticks can be neatly stored in a compartment on the base of the burner, which can be opened from the side allowing for the sticks to easily slide out.   The top portion is used to hold & light the incense sticks, and once lit, the lid can be closed and placed anywhere in the room. As the incense burns, residue is dropped on the tray, while the freshness and fragrance of the incense sticks quietly seep through the wooden passageways and encompass the room in which the burner is placed.","images":["https://m.media-amazon.com/images/I/81-6sJXV8-L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Govinda","source_asin":"B08R9NHSM1","category_path":"Home & Kitchen"},"sku":"BM-770538","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08R9NHSM1","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08R9NHSM1","price_pending":true,"merchant_ready":false});
